-----------------------
-- Thanos snap to update 1/8 of the COS test data to BC Parks
-----------------------

UPDATE complaint
SET owned_by_agency_code_ref = 'PARKS'
WHERE CAST(SUBSTRING(complaint_identifier FROM 4 FOR 6) AS INTEGER) % 8 = 0
AND owned_by_agency_code_ref = 'COS';

---------------------
-- These ones are part of our Cypress Tests and should be saved
---------------------
UPDATE complaint
SET owned_by_agency_code_ref = 'COS'
WHERE complaint_identifier IN ('23-031744', '23-006888', '23-032456');

---------------------
-- Update complaint_type_code for test data
---------------------

UPDATE complaint c1 SET complaint_type_code = 
CASE WHEN a.allegation_complaint_guid IS NOT NULL THEN 'ERS'
	 WHEN hc.hwcr_complaint_guid IS NOT NULL THEN 'HWCR'
	 WHEN gc.gir_complaint_guid IS NOT NULL THEN 'GIR'
END
FROM complaint c2
LEFT JOIN allegation_complaint a ON c2.complaint_identifier = a.complaint_identifier
LEFT JOIN hwcr_complaint hc ON c2.complaint_identifier = hc.complaint_identifier
LEFT JOIN gir_complaint gc ON c2.complaint_identifier = gc.complaint_identifier
WHERE c1.complaint_identifier = c2.complaint_identifier;

UPDATE complaint SET complaint_type_code = 'HWCR' WHERE complaint_identifier = '23-007000';

-- CE-14 - Convert incident times to UTC format
-- default to PDT in cases where the original timezones aren't known

-- The data was stored with a PDT offset.  Change this to UTC by adding 7 hours
update complaint set incident_utc_date = (incident_utc_date + incident_utc_time + interval '7 hours')::DATE, incident_utc_time = (incident_utc_date + incident_utc_time + interval '7 hours')::TIME, incident_reported_utc_timestmp = incident_reported_utc_timestmp + interval '7 hours', update_utc_timestamp = update_utc_timestamp + interval '7 hours';

UPDATE complaint SET owned_by_agency_code_ref = 'EPO'
FROM allegation_complaint
WHERE complaint.complaint_identifier = allegation_complaint.complaint_identifier 
   AND allegation_complaint.violation_code = 'WASTE'
   AND complaint.owned_by_agency_code_ref IS NULL;

UPDATE complaint SET owned_by_agency_code_ref = 'EPO'
FROM allegation_complaint 
WHERE complaint.complaint_identifier = allegation_complaint.complaint_identifier 
   AND allegation_complaint.violation_code = 'PESTICDE'
   AND complaint.owned_by_agency_code_ref IS NULL;

UPDATE complaint SET owned_by_agency_code_ref = 'COS'
FROM allegation_complaint 
WHERE complaint.owned_by_agency_code_ref IS NULL


