INSERT INTO complaint(complaint_identifier,detail_text,caller_name,caller_address,caller_email,caller_phone_1,caller_phone_2,caller_phone_3,location_summary_text,location_detailed_text, incident_utc_date, incident_utc_time, incident_reported_utc_timestmp,reported_by_other_text, create_user_id,create_utc_timestamp,update_user_id,update_utc_timestamp, reported_by_code, owned_by_agency_code_ref, complaint_status_code, geo_organization_unit_code, location_geometry_point) VALUES('23-028534','Judy left a voice mail with the Sea to Sky Natural Resource District office, Ministry of Forests, on the weekend of July 15-16, 2023 regarding a bear that is rummaging through garbage in the backyard of the house behind her. She did not see the bear during the latest incident, but heard it and says the bear has been frequenting the neighbourhood over the past two weeks. She describes the bear as large and non-aggressive towards people. She says "it is terrorizing everybody in the neighbourhood" and tearing apart garbage cans. The bear has so far destroyed two garbage cans. It was chased off by a neighbour''s dog during the latest incident and is crossing over a fence to access the lot. We gave her the RAPP 1-877 number to report incidents and indicated the Ministry (FrontCounter BC) would file an online complaint to alert Conservation Officers to the bear. ',null,null,null,null,null,null,'38767 Garibaldi Ave, Squamish, BC',null,'2023-07-17','09:20:22','2023-07-17 09:20:22',null,'CROCHON@idir','2023-07-19 12:57:01',null,null,null,null,'OPEN','SQUMISH',ST_GeomFromText('POINT(-123.1549925 49.7112948)')) ON CONFLICT DO NOTHING;
